const gui_font_registry_entry_t *gui_font_registry(void) { return s_font_registry; }
size_t gui_font_registry_count(void) { return sizeof(s_font_registry) / sizeof(s_font_registry[0]); }

const gui_font_t *gui_font_find_by_id(const char *id) {
    if (id == NULL) return NULL;
    for (size_t i = 0; i < gui_font_registry_count(); ++i) {
        if (s_font_registry[i].id != NULL && strcmp(s_font_registry[i].id, id) == 0) return s_font_registry[i].font;
    }
    return NULL;
}

const gui_font_t *gui_font_find_face(const char *family, uint16_t size, gui_font_style_t style) {
    if (family == NULL) return NULL;
    for (size_t i = 0; i < gui_font_registry_count(); ++i) {
        if (s_font_registry[i].family != NULL && strcmp(s_font_registry[i].family, family) == 0 && s_font_registry[i].size == size && s_font_registry[i].style == style) return s_font_registry[i].font;
    }
    return NULL;
}

